describe('Admin Contacts & Inquiries - Message List & Filtering', () => {
  const mockInboxMessages = [
    {
      id: 'msg-1',
      name: 'Alice Walker',
      email: 'alice@example.com',
      subject: 'Catering Inquiry for Wedding',
      message: 'Hello, I would love to ask about catering options for next summer.',
      is_read: false,
      is_archived: false,
      snoozed_until: null,
      deleted_at: null,
      created_at: '2026-11-18T10:00:00.000Z',
    },
    {
      id: 'msg-2',
      name: 'Bob Smith',
      email: 'bob@example.com',
      subject: 'Recipe Question: Garlic Chicken',
      message: 'Can I substitute dried rosemary instead of fresh in the skillet chicken?',
      is_read: true,
      is_archived: false,
      snoozed_until: null,
      deleted_at: null,
      created_at: '2026-11-17T14:30:00.000Z',
    },
  ];

  const mockSnoozedMessages = [
    {
      id: 'msg-3',
      name: 'Charlie Day',
      email: 'charlie@example.com',
      subject: 'Partnership Proposal',
      message: 'Let us collaborate on a seasonal Thanksgiving special.',
      is_read: true,
      is_archived: false,
      snoozed_until: '2099-01-01T00:00:00.000Z',
      deleted_at: null,
      created_at: '2026-11-16T12:00:00.000Z',
    },
  ];

  beforeEach(() => {
    // Authenticate as active member with tenant sandbox
    cy.intercept('GET', '**/auth/me*', {
      statusCode: 200,
      body: {
        user: {
          username: 'delisha',
          email: 'delisha@example.com',
        },
      },
    }).as('getCurrentUser');

    cy.intercept('GET', '**/auth/session*', {
      statusCode: 200,
      body: {
        role: 'member',
        status: 'active',
        tenant: {
          id: 't-1',
          name: "Delisha's Kitchen",
          slug: 'delisha-kitchen',
        },
        isImpersonating: false,
      },
    }).as('getMemberSession');
  });

  it('visit contacts inbox → displays folder navigation and list of messages with sender and snippet', () => {
    cy.intercept('GET', '**/api/contacts?folder=inbox*', {
      statusCode: 200,
      body: { data: mockInboxMessages, count: 2 },
    }).as('getInboxMessages');

    cy.visit('/contacts');
    cy.wait('@getInboxMessages');

    // Page header
    cy.contains('h1', 'Contacts & Inquiries').should('be.visible');

    // Folders
    cy.contains('button', 'Inbox').should('be.visible');
    cy.contains('button', 'Snoozed').should('be.visible');
    cy.contains('button', 'All Mail').should('be.visible');
    cy.contains('button', 'Trash').should('be.visible');

    // Message 1 (unread, bold sender)
    cy.contains('Alice Walker').should('be.visible');
    cy.contains('Catering Inquiry for Wedding').should('be.visible');
    cy.contains('Hello, I would love to ask about catering options').should('be.visible');

    // Message 2 (read)
    cy.contains('Bob Smith').should('be.visible');
    cy.contains('Recipe Question: Garlic Chicken').should('be.visible');
  });

  it('switch folder to Snoozed → displays snoozed messages list', () => {
    cy.intercept('GET', '**/api/contacts?folder=inbox*', {
      statusCode: 200,
      body: { data: mockInboxMessages, count: 2 },
    }).as('getInboxMessages');

    cy.intercept('GET', '**/api/contacts?folder=snoozed*', {
      statusCode: 200,
      body: { data: mockSnoozedMessages, count: 1 },
    }).as('getSnoozedMessages');

    cy.visit('/contacts');
    cy.wait('@getInboxMessages');

    cy.contains('button', 'Snoozed').click();
    cy.wait('@getSnoozedMessages');

    cy.url().should('include', 'folder=snoozed');
    cy.contains('Charlie Day').should('be.visible');
    cy.contains('Partnership Proposal').should('be.visible');
  });

  it('switch folder to Trash with no items → displays empty trash illustration and notice', () => {
    cy.intercept('GET', '**/api/contacts?folder=inbox*', {
      statusCode: 200,
      body: { data: mockInboxMessages, count: 2 },
    }).as('getInboxMessages');

    cy.intercept('GET', '**/api/contacts?folder=trash*', {
      statusCode: 200,
      body: { data: [], count: 0 },
    }).as('getTrashMessages');

    cy.visit('/contacts');
    cy.wait('@getInboxMessages');

    cy.contains('button', 'Trash').click();
    cy.wait('@getTrashMessages');

    cy.contains('Your trash is empty').should('be.visible');
    cy.contains(
      'Messages that have been in Trash more than 30 days will be automatically deleted.',
    ).should('be.visible');
  });
});

describe('Admin Contacts & Inquiries - Message Detail Flow', () => {
  const detailMessage = {
    id: 'msg-1',
    name: 'Alice Walker',
    email: 'alice@example.com',
    subject: 'Catering Inquiry for Wedding',
    message: 'Hello, I would love to ask about catering options for next summer.',
    is_read: false,
    is_archived: false,
    snoozed_until: null,
    deleted_at: null,
    created_at: '2026-11-18T10:00:00.000Z',
  };

  beforeEach(() => {
    cy.intercept('GET', '**/auth/me*', {
      statusCode: 200,
      body: {
        user: {
          username: 'delisha',
          email: 'delisha@example.com',
        },
      },
    }).as('getCurrentUser');

    cy.intercept('GET', '**/auth/session*', {
      statusCode: 200,
      body: {
        role: 'member',
        status: 'active',
        tenant: {
          id: 't-1',
          name: "Delisha's Kitchen",
          slug: 'delisha-kitchen',
        },
        isImpersonating: false,
      },
    }).as('getMemberSession');
  });

  it('click message row in inbox → navigates to message detail view with full content', () => {
    cy.intercept('GET', '**/api/contacts?folder=inbox*', {
      statusCode: 200,
      body: { data: [detailMessage], count: 1 },
    }).as('getInboxMessages');

    cy.intercept('GET', '**/api/contacts/msg-1', {
      statusCode: 200,
      body: detailMessage,
    }).as('getMessageDetail');

    cy.intercept('PUT', '**/api/contacts/msg-1', {
      statusCode: 200,
      body: { ...detailMessage, is_read: true },
    }).as('updateMessageRead');

    cy.visit('/contacts');
    cy.wait('@getInboxMessages');

    // Click on message to open detail view
    cy.contains('Alice Walker').click();
    cy.wait('@getMessageDetail');

    cy.url().should('include', '/contacts/msg-1');

    // Verify detail components
    cy.contains('h1', 'Catering Inquiry for Wedding').should('be.visible');
    cy.contains('Alice Walker').should('be.visible');
    cy.contains('<alice@example.com>').should('be.visible');
    cy.contains('Hello, I would love to ask about catering options for next summer.').should(
      'be.visible',
    );

    // Return to Inbox via back button
    cy.get('button[mattooltip="Back to Inbox"]').click();
    cy.url().should('match', /\/contacts$/);
  });
});

describe('Admin Contacts & Inquiries - Snooze Dialog', () => {
  const testMessage = {
    id: 'msg-1',
    name: 'Alice Walker',
    email: 'alice@example.com',
    subject: 'Catering Inquiry for Wedding',
    message: 'Hello, I would love to ask about catering options for next summer.',
    is_read: true,
    is_archived: false,
    snoozed_until: null,
    deleted_at: null,
    created_at: '2026-11-18T10:00:00.000Z',
  };

  beforeEach(() => {
    cy.intercept('GET', '**/auth/me*', {
      statusCode: 200,
      body: {
        user: {
          username: 'delisha',
          email: 'delisha@example.com',
        },
      },
    }).as('getCurrentUser');

    cy.intercept('GET', '**/auth/session*', {
      statusCode: 200,
      body: {
        role: 'member',
        status: 'active',
        tenant: {
          id: 't-1',
          name: "Delisha's Kitchen",
          slug: 'delisha-kitchen',
        },
        isImpersonating: false,
      },
    }).as('getMemberSession');
  });

  it('select message and open snooze date picker dialog → shows calendar and save button', () => {
    cy.intercept('GET', '**/api/contacts?folder=inbox*', {
      statusCode: 200,
      body: { data: [testMessage], count: 1 },
    }).as('getInboxMessages');

    cy.visit('/contacts');
    cy.wait('@getInboxMessages');

    // Select the message checkbox
    cy.get('mat-checkbox').first().click();

    // Click Snooze in toolbar
    cy.get('button[mattooltip="Snooze"]').click();

    // Click custom date & time option in dropdown
    cy.contains('button', 'Pick date & time').click();

    // Verify dialog opens
    cy.get('mat-dialog-container').should('be.visible');
    cy.get('mat-dialog-container').contains('Pick date & time').should('be.visible');
    cy.get('#date-input').should('be.visible');
    cy.get('#time-input').should('be.visible');
    cy.contains('button', 'Save').should('be.visible');

    // Close dialog
    cy.contains('button', 'Cancel').click();
    cy.get('mat-dialog-container').should('not.exist');
  });
});

describe('Admin Contacts & Inquiries - Access Protection Guard', () => {
  it('platform admin without impersonation visits /contacts → redirects to /users', () => {
    cy.intercept('GET', '**/auth/me*', {
      statusCode: 200,
      body: {
        user: {
          username: 'superadmin',
          email: 'admin@platform.com',
        },
      },
    }).as('getAdminUser');

    cy.intercept('GET', '**/auth/session*', {
      statusCode: 200,
      body: {
        role: 'admin',
        status: 'active',
        tenant: null,
        isImpersonating: false,
      },
    }).as('getAdminSession');

    cy.intercept('GET', '**/api/admin/users*', {
      statusCode: 200,
      body: { users: [] },
    }).as('getUsers');

    cy.intercept('GET', '**/api/admin/waiting-room*', {
      statusCode: 200,
      body: { pendingUsers: [] },
    }).as('getWaitingRoom');

    cy.visit('/contacts');

    // authGuard tenant isolation checks that direct admin visits redirect to /users
    cy.url().should('include', '/users');
  });
});
